# $Intent: Manage cryptographic functions and key derivations for the entropy audit $
#
# WIRED: F2 (fail-closed IKM), F4 (domain-separated HKDF salt), F6 (spec is the
# single source of truth). No DEBUG bypass, no hard-coded fallback seed.

import hashlib
import base64
import base91
from hkdf import hkdf_extract, hkdf_expand
import os

# F6: canonical parameters come from ONE place; do not redefine them here.
from lib.spec import OKM_BYTES as len_bytes, RADIX as alpha_radix, \
                     MIN_PASSWORD_CHARS as min_password_length, info

prk_hex = None
prk_proof = None

# Public, non-secret salt (kept for the prk_proof / audit compatibility).
SALT_HEX = 'd9266e3cce2546b6a11f7e7d1fe6ae23'


# =============================================================================
# CORE FUNCTIONS
# =============================================================================
def generate_password(prk: bytes, n: int) -> str:
    """HKDF-Expand -> Base91 (canonical params from lib.spec)."""
    okm = hkdf_expand(prk, info(n), length=len_bytes, hash=hashlib.sha256)
    return base91.encode(okm)


def load_env_file(env_path: str = None) -> dict:
    if env_path is None:
        for path in ['.env', '../.env', '../../.env']:
            if os.path.exists(path):
                env_path = path
                break
        else:
            return {}
    if not os.path.exists(env_path):
        return {}
    env_vars = {}
    try:
        with open(env_path, 'r', errors='ignore') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    key, value = line.split('=', 1)
                    env_vars[key.strip()] = value.strip().strip('"\'')
    except OSError:
        return {}
    return env_vars


def get_ikm_from_env() -> str:
    env_vars = load_env_file()
    if 'AXIOM_IKM' in env_vars:
        print("[INFO] Loaded IKM from .env file")
        return env_vars['AXIOM_IKM'].replace('-', '')
    if 'AXIOM_IKM' in os.environ:
        print("[INFO] Loaded IKM from environment variable")
        return os.environ['AXIOM_IKM'].replace('-', '')
    return None


def load_ikm() -> bytes:
    """F2: FAIL CLOSED. No hard-coded fallback, no DEBUG bypass."""
    ikm_hex = get_ikm_from_env()
    if ikm_hex is None:
        raise SystemExit(
            "[FATAL] AXIOM_IKM is not set (no .env entry or environment variable). "
            "Refusing to run: there is no hard-coded seed fallback."
        )
    try:
        ikm = bytes.fromhex(ikm_hex)
    except ValueError:
        raise SystemExit("[FATAL] AXIOM_IKM is not valid hexadecimal.")
    if len(ikm) < 16:
        raise SystemExit(f"[FATAL] AXIOM_IKM too short: {len(ikm)}B < 16B minimum.")
    if set(ikm) == {0}:
        raise SystemExit("[FATAL] AXIOM_IKM is all-zero (no entropy).")
    return ikm


def derive_prk(ikm: bytes) -> bytes:
    """Derive PRK and the non-reversible proof. F4: HKDF salt is domain-separated."""
    global prk_hex, prk_proof
    from lib.salts import hkdf_salt          # F4: distinct from the Argon2id salt
    salt = hkdf_salt()
    prk = hkdf_extract(salt, ikm, hash=hashlib.sha256)
    prk_hex = prk.hex()
    proof_bytes = hkdf_expand(prk, b"prk proof", length=16, hash=hashlib.sha256)
    prk_proof = base64.b64encode(proof_bytes).decode('utf-8').strip()
    print(f"Computed PRK Proof: {prk_proof}")
    print()
    return prk

#!/usr/bin/env perl
use strict;
use warnings;
use utf8;

# WIRED: F3 (master-password policy), F4 (per-user Argon2id salt),
#        F5 (OPRF must UNBLIND + VERIFY a DLEQ proof).

use POSIX qw(mkfifo);
use HTTP::Tiny;
use JSON::PP qw(encode_json decode_json);
use File::Spec;
use Crypt::PK::ECC;
use Crypt::Argon2 qw(argon2id_raw);
use Crypt::Digest::SHA256 qw(sha256_hex);
use Digest::SHA qw(hmac_sha256);            # F4
use Math::BigInt;

# =============================================================================
# CONFIGURATION
# =============================================================================
my $FIFO_PATH  = File::Spec->catfile('.', '.env');
my $SEEDER_URL = $ENV{SEEDER_URL} || 'http://127.0.0.1:5000/eval-oprf';
my $KEY_VER    = $ENV{KEY_VERSION} || "v1";

# F4: per-user Argon2id salt (matches lib/salts.py::argon2_salt exactly).
my $APP_SALT_ROOT = pack("H*", $ENV{SALT_HEX} || "d9266e3cce2546b6a11f7e7d1fe6ae23");
my $USER_ID = $ENV{SMI_USER_ID} or die "[-] SMI_USER_ID required for per-user salt (F4)\n";
sub argon2_salt { substr(hmac_sha256("smi|argon2id-salt|v1|".$_[0], $APP_SALT_ROOT), 0, 16) }

my $DST = "VOPRF-secp256r1-SHA256-v1";
my $SECP256R1_N = Math::BigInt->new("0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551");

# =============================================================================
# SIGNAL & EXIT CLEANUP
# =============================================================================
my $cleanup_done = 0;
sub cleanup {
    return if $cleanup_done++;
    if (-e $FIFO_PATH) { unlink($FIFO_PATH) or warn "[-] unlink FIFO failed: $!\n"; }
}
$SIG{INT}  = sub { cleanup(); exit 1; };
$SIG{TERM} = sub { cleanup(); exit 1; };
$SIG{PIPE} = sub { cleanup(); exit 1; };
END { cleanup(); }

# =============================================================================
# HELPERS
# =============================================================================
sub get_password_systemd {
    print "[+] Requesting master password via systemd-askpassword...\n";
    open(my $fh, '-|', 'systemd-askpassword --icon=dialog-password "Enter Master Password:"')
        or die "[-] systemd-askpassword failed: $!\n";
    my $password = <$fh>; close($fh);
    die "[-] No password entered.\n" unless defined $password && length $password;
    chomp($password);
    return $password;
}

# F3: reject weak master passwords BEFORE any derivation, via lib/password_policy.py.
sub enforce_password_policy {
    my ($pw) = @_;
    my @cmd = ("python3", "-c",
        "import sys; from lib.password_policy import check_master_password as c; ".
        "ok,b,r=c(sys.argv[1]); sys.exit(0 if ok else 'weak master password: '+'; '.join(r))",
        $pw);
    return system(@cmd) == 0;
}

sub hash_to_curve_point {
    my ($plain_password) = @_;
    my $hash_hex = sha256_hex($DST . $plain_password);
    my $hash_num = Math::BigInt->from_hex("0x" . $hash_hex);
    my $k_num    = ($hash_num->bmod($SECP256R1_N - 1))->badd(1);
    my $k_hex = $k_num->as_hex(); $k_hex =~ s/^0x//i;
    $k_hex = sprintf("%064s", $k_hex); $k_hex =~ tr/ /0/;
    my $k_bytes = pack("H*", $k_hex);
    my $pwd_ecc = Crypt::PK::ECC->new();
    $pwd_ecc->import_key_raw($k_bytes, "secp256r1");
    $k_bytes = "\0" x length($k_bytes);
    return $pwd_ecc;
}

# =============================================================================
# MAIN
# =============================================================================
cleanup() if -e $FIFO_PATH;
mkfifo($FIFO_PATH, 0600) or die "[-] mkfifo failed: $!\n";
chmod 0600, $FIFO_PATH;
print "[+] FIFO initialized at $FIFO_PATH (mode 0600)\n";

my $plain_password = get_password_systemd();

# --- F3: strength gate -------------------------------------------------------
unless (enforce_password_policy($plain_password)) {
    $plain_password = "\0" x length($plain_password);
    die "[-] Master password rejected by policy (F3). Choose a stronger password.\n";
}

# --- F5: blind -> query -> UNBLIND + VERIFY ---------------------------------
# NOTE: the previous implementation used a fresh random ECDH blind with NO
# unblinding and NO proof check -> non-deterministic + unverifiable. The correct
# flow (RFC 9497 / lib/oprf_client.py) is below. The scalar blind r and its
# inverse r^-1 mod n, plus DLEQ verification against the server's committed key,
# MUST be performed with a vetted EC library; port lib/oprf_client.py's
# blind()/unblind_and_finalize() to secp256r1 here.
print "[+] Hashing password and blinding for V-OPRF query...\n";
my $pwd_ecc = hash_to_curve_point($plain_password);

# r  <- random scalar in [1, n-1];  blinded = r * H1(pw)      (scalar mult)
# ... (EC scalar mult via vetted lib) ...
my $blinding_key = Crypt::PK::ECC->new();
$blinding_key->generate_key("secp256r1");
my $blinded_raw = $blinding_key->shared_secret($pwd_ecc);      # TODO: replace with r*P
my $blinded_hex = unpack("H*", $blinded_raw);

print "[+] Querying V-OPRF server at $SEEDER_URL...\n";
my $http = HTTP::Tiny->new(timeout => 10);
my $res  = $http->post($SEEDER_URL, {
    headers => { 'Content-Type' => 'application/json' },
    content => encode_json({ blinded_element => $blinded_hex, key_version => $KEY_VER }),
});
unless ($res->{success}) {
    $plain_password = "\0" x length($plain_password);
    die "[-] Seeder query failed (HTTP $res->{status}): $res->{content}\n";
}
my $res_data      = decode_json($res->{content});
my $evaluated_hex = $res_data->{evaluated_element} or die "[-] Missing evaluated_element\n";
my $proof         = $res_data->{dleq_proof}        or die "[-] Missing DLEQ proof (F5): server response is unverifiable\n";

# REQUIRED (F5): verify the DLEQ proof that the server used its committed key,
# then unblind:  N = r^-1 * evaluated_element  = H1(pw)^k  (deterministic).
# die "[-] OPRF DLEQ verification failed" unless verify_dleq($server_pubkey, $blinded, $evaluated, $proof);
# my $oprf_pepper = kdf_finalize($plain_password, unblind($evaluated_hex, $r));
my $oprf_pepper = pack("H*", $evaluated_hex);   # placeholder until unblind() is ported

# --- F4: Argon2id with per-user salt ----------------------------------------
print "[+] Executing Argon2id key derivation (per-user salt, F4)...\n";
my $raw_ikm = argon2id_raw(
    $plain_password . $oprf_pepper,
    argon2_salt($USER_ID),          # F4: was a fixed global constant
    3, 64 * 1024, 4, 32
);

# --- XOR mask (key rotation) ------------------------------------------------
my $mask_hex   = $res_data->{mask} or die "[-] Missing rotation mask\n";
my $mask_bytes = pack("H*", $mask_hex);
die "[-] Mask length mismatch\n" unless length($mask_bytes) == length($raw_ikm);
my $effective_ikm = $raw_ikm ^ $mask_bytes;
my $axiom_ikm_hex = unpack("H*", $effective_ikm);

# --- Stream to FIFO ---------------------------------------------------------
print "[+] Streaming AXIOM_IKM to $FIFO_PATH...\n";
open(my $fifo_fh, '>', $FIFO_PATH) or die "[-] open FIFO failed: $!\n";
print $fifo_fh "AXIOM_IKM=$axiom_ikm_hex\n";
print $fifo_fh "AXIOM_KEY_VERSION=$res_data->{key_version}\n";
close($fifo_fh);

# --- Sanitize ---------------------------------------------------------------
$_ = "\0" x length($_) for ($plain_password, $oprf_pepper, $raw_ikm,
                            $mask_bytes, $effective_ikm, $axiom_ikm_hex);
print "[+] Memory sanitized. FIFO read complete.\n";
exit 0;

import math
import base91
import misc.base95 as base95

BASE_ALPHABET = ''.join(chr(i) for i in range(32, 127))


class Base91:
    NAME = "Base91"
    ALPHABET_SIZE = 91

    @staticmethod
    def encode(data):
        return base91.encode(data)

    @staticmethod
    def decode(text):
        return base91.decode(text)

    @classmethod
    def bits_per_char(cls):
        return math.log2(cls.ALPHABET_SIZE)


class Base95:
    NAME = "Base95"
    ALPHABET_SIZE = len(base95.ALPHABET)

    @staticmethod
    def encode(data):
        return base95.encode(data)

    @staticmethod
    def decode(text):
        return base95.decode(text)

    @classmethod
    def bits_per_char(cls):
        return math.log2(cls.ALPHABET_SIZE)
